Fetch starts two owned workers. client.Get(ctx, name) honors cancellation and closes its own response body before returning. A caller can cancel after both Get calls return but before either result is received. The result channel is unbuffered. On return, Fetch must have stopped and joined its workers; callers must receive context cancellation rather than a success result. Do not assume closing the channel stops a sender safely.
package worker
import "context"
type Client interface { Get(context.Context, string) (string, error) }
func Fetch(ctx context.Context, client Client) ([]string, error) {
 results := make(chan string)
 for _, name := range []string{"a", "b"} {
  go func(name string) { value, _ := client.Get(ctx, name); results <- value }(name)
 }
 out := []string{}
 for range 2 {
  select {
  case <-ctx.Done(): return nil, ctx.Err()
  case value := <-results: out = append(out, value)
  }
 }
 return out, nil
}
